-- ---------------------------------------------------------------------------
-- bob_app_config (2 rows — PLACEHOLDERS for production credentials)
-- ---------------------------------------------------------------------------
/*
 * WHY: worker_url must point to the production edge function URL, and
 * worker_auth must be the production project's service-role JWT. These values
 * are environment-specific and cannot be copied from dev. Fill them manually
 * after deploying the assessment-eval-worker edge function to production.
 * ON CONFLICT DO NOTHING ensures a re-run never overwrites already-set creds.
 */
ON CONFLICT (key) DO NOTHING;


-- ---------------------------------------------------------------------------
-- Reset sequences for tables with bigint id
-- ---------------------------------------------------------------------------
SELECT setval('bob_vocabulary_id_seq', (SELECT COALESCE(MAX(id), 1) FROM bob_vocabulary));



COMMIT;
